<div class="va-shop-page"><div class="va-static-hero"><div><span>Your saved products</span><h1>Wishlist</h1></div><nav><a href="<?= base_url() ?>">Home</a> / Wishlist</nav></div><?php if (empty($shop_items)): ?><div class="va-shop-empty"><i class="bi bi-heart"></i><h2>Your wishlist is empty</h2><a class="btn va-why-button" href="<?= base_url('accessories') ?>">Explore Products</a></div><?php else: ?><div class="va-list-page"><?php foreach($shop_items as $item): ?><article class="va-saved-item"><button class="shop-action va-remove" data-action="remove-wishlist" data-product-id="<?= $item->id ?>">×</button><?php if($item->primary_image): ?><img src="<?= $item->primary_image ?>" alt=""><?php endif; ?><div><h2><?= html_escape($item->name) ?></h2><span>&#8377; <?= number_format($item->price) ?></span><small>In stock</small></div><button class="btn va-why-button shop-action" data-action="cart" data-product-id="<?= $item->id ?>">Add to Cart</button></article><?php endforeach; ?></div><?php endif; ?></div>
